import sys,json,pathlib
try:
    d=json.loads(sys.stdin.read())
except Exception:
    sys.exit(0)
if d.get('stop_hook_active'):
    sys.exit(0)
p=pathlib.Path(sys.argv[1])
if p.exists():
    sys.stdout.buffer.write(json.dumps({'decision':'block','reason':p.read_text('utf-8')},ensure_ascii=False).encode('utf-8'))
